#!/usr/bin/env bash
# Generated by Dagly, profile helio_catalog_artifact_v1. Run before dispatch, review, commit.
# Resolves each locked material's branch head once into cicd/helio-materials.lock.json.
set -euo pipefail
# Authenticates as YOU, through git: gh's login is offered as a credential
# helper when gh is installed, and git's own helpers and URL rewrites apply
# either way. The deploy's credential (a token secret or a GitHub App) is for
# the runner and is not used here; you need read access to each repository.
resolve() {
  if command -v gh >/dev/null 2>&1; then
    rev="$(git -c 'credential.helper=!gh auth git-credential' ls-remote "https://github.com/$2.git" "refs/heads/$3" | cut -f1)"
  else
    rev="$(git ls-remote "https://github.com/$2.git" "refs/heads/$3" | cut -f1)"
  fi
  [[ "$rev" =~ ^[a-f0-9]{40}$ ]] || { echo "cannot resolve $1 ($2 $3): sign in with gh auth login, or configure git credentials with read access to $2" >&2; exit 1; }
  printf '%s\t%s\t%s\t%s\n' "$1" "$2" "$3" "$rev"
}
{
  resolve 'ansible' 'helloangular/bm-sellside-ansible-20261028' 'master'
} | python3 -c '
import json, sys
materials = {}
for line in sys.stdin:
    name, repository, branch, revision = line.rstrip("\n").split("\t")
    materials[name] = {"repository": repository, "branch": branch, "revision": revision}
json.dump({"version": 1, "materials": materials}, open(sys.argv[1], "w"), sort_keys=True)
' cicd/helio-materials.lock.json
echo "wrote cicd/helio-materials.lock.json; commit it before dispatching the release workflow"
